  const who=(c:any)=>c?`<code>${esc(c.account)}</code> · ${T('tin cậy','trust')} <strong>${c.trust==null?'—':Number(c.trust).toFixed(2)}</strong>${c.banned?' '+chip('disabled',T('Đã chặn','Banned')):''}${(c.flags||[]).map((f:string)=>' '+chip('amber',flagName(f))).join('')}`:'—';
  const actions=(x:any)=>{if(!owner)return '';const b=(a:string,l:string,extra='')=>`<button class="btn small" data-ca="${a}" data-id="${esc(x.id||'')}" data-group="${esc(x.groupId||'')}" data-state="${esc(x.state||'')}" data-item="${esc(x.itemId||'')}" data-account="${esc(x.contributor?.account||'')}" data-shop="${esc(x.shop||'')}" data-price="${esc(x.priceId||'')}" ${extra}>${l}</button>`;
   if(x.kind==='reported')return b('dismiss-reports',T('Giữ giá, bỏ báo cáo','Keep, dismiss'))+(x.hiddenGroup?b('restore',T('Khôi phục','Restore')):b('hide',T('Ẩn giá','Hide price')));
   if(x.kind==='shop-reported')return b('shop-dismiss',T('Bỏ báo cáo','Dismiss'))+(x.hidden?b('shop-restore',T('Khôi phục','Restore')):b('shop-hide',T('Ẩn giá tiệm','Hide shop price')));
   return b('approve',T('Duyệt','Approve'))+b('reject',T('Từ chối','Reject'))+b('hide',T('Ẩn','Hide'))+(x.contributor?.banned?b('unban',T('Bỏ chặn','Unban')):b('ban',T('Chặn người gửi','Ban contributor')))};
  const queueRows=d.queue.map((x:any)=>({...x}));
  const tabs=[['queue',T('Hàng đợi kiểm duyệt','Moderation queue')+` (${d.queue.length})`],['shops',T('Tiệm','Shops')+` (${d.applications.filter((a:any)=>a.status==='pending').length})`],['coi',T('Tín hiệu xung đột lợi ích','Conflict-of-interest signals')+` (${d.coi.length})`],['rules',T('Quy tắc','Rules')]];
  el.innerHTML=section(T('Cộng đồng giá','Community prices'),T('Thử nghiệm giá cộng đồng: chỉ ảnh kệ giá và hóa đơn, ẩn danh với người dùng. Mọi lần xem và thao tác đều ghi nhật ký kiểm tra.','Community price pilot: shelf-tag photos and receipts only, anonymous to users. Every view and action is written to the audit log.'),
  `<form class="card form" id="cpf"><h2>${T('Chế độ thử nghiệm','Pilot')}</h2><label class="check"><input type="checkbox" name="on" ${d.pilot.enabled?'checked':''} ${!owner||locked?'disabled':''}> <span>${T('Bật giá cộng đồng','Community prices on')} ${locked?`<span class="src env">${T('biến môi trường','environment')}</span>`:''}</span></label><p class="muted">${T('Bang: ','States: ')}${esc(d.pilot.states.join(', ')||'—')} · ${T('Tắt: người dùng không thấy gì thay đổi. Bang lấy từ “Bang hỗ trợ Price Scout” (chỉ NSW, QLD).','Off: users see no change. States come from “Price Scout states” (NSW and QLD only).')}</p>${owner&&!locked?`<button class="btn primary">${T('Lưu','Save')}</button>`:''}</form>
  <div class="tiles">${[
   tile(T('Lượt gửi','Submissions'),num(st.submissions),T(`Trong 40 ngày gần nhất. ${st.rejected} bị từ chối, ${st.hidden} bị ẩn.`,`Last 40 days. ${st.rejected} rejected, ${st.hidden} hidden.`)),
   tile(T('Đã xác nhận','Confirmed'),num(st.confirmed),T('Nhóm giá có ≥2 gia đình khớp trong 7 ngày, hoặc 1 hóa đơn từ người tin cậy ≥0.7.','Price groups with ≥2 matching families within 7 days, or 1 receipt from trust ≥0.7.')),
   tile(T('Chờ xác nhận','Pending'),num(st.pending),T('Chỉ hiện như gợi ý, không tính vào tổng.','Shown as hints only, never in totals.')),
   tile(T('Đang giữ','Held'),num(st.held),T('Giá bất thường chờ duyệt, không hiển thị.','Outliers awaiting review, not shown.'),st.held?'warn':''),
   tile(T('Báo cáo mở','Open reports'),num(st.reportsOpen),T('Người dùng bấm “Báo giá sai”.','Users tapped “Report wrong price”.'),st.reportsOpen?'warn':''),
   tile(T('Người đóng góp','Contributors'),num(st.contributors),T(`${st.banned} bị chặn. Tin cậy: <0.3 ${st.trust['<0.3']} · 0.3–0.7 ${st.trust['0.3–0.7']} · ≥0.7 ${st.trust['≥0.7']}`,`${st.banned} banned. Trust: <0.3 ${st.trust['<0.3']} · 0.3–0.7 ${st.trust['0.3–0.7']} · ≥0.7 ${st.trust['≥0.7']}`))].join('')}</div>
  ${hbars([[T('Tin cậy < 0.3 (không tính)','Trust < 0.3 (not counted)'),st.trust['<0.3']],['0.3–0.7',st.trust['0.3–0.7']],['≥ 0.7',st.trust['≥0.7']]],T('Phân bố độ tin cậy','Trust distribution'))}
  <div class="tabs" role="tablist">${tabs.map(([k,l])=>`<button role="tab" class="btn ${s.tab===k?'primary':''}" aria-selected="${s.tab===k}" data-tab="${k}">${esc(l)}</button>`).join('')}</div>
  <div id="cptab">${s.tab==='queue'?table([
   {label:T('Loại','Kind'),render:(x:any)=>chip(x.kind==='held'||x.kind==='flagged'?'amber':'red',kindName(x.kind))+(x.holdReason?`<br><small>${esc(holdName(x.holdReason))}</small>`:'')+((x.flags||[]).length?`<br><small>${x.flags.map((f:string)=>esc(flagName(f))).join(', ')}</small>`:'')},
   {label:T('Món · cửa hàng','Item · store'),render:(x:any)=>`<strong>${esc(x.label||x.itemId)}</strong><br><small>${esc(x.retailer||'')}${x.shopName?esc(x.shopName):''} · ${esc(x.branchLabel||'')} · ${esc(x.state||'')}</small>`},
   {label:T('Giá','Price'),render:(x:any)=>`${money(x.price)}${x.unitPrice!=null?`<br><small>${money(x.unitPrice)} ${esc(String(x.unitBasis||'').replace('per_','/'))}</small>`:''}${x.families!=null?`<br><small>${T(x.families+' gia đình',x.families+' families')}</small>`:''}`},
   {label:T('Bằng chứng','Evidence'),render:(x:any)=>x.kind==='reported'?(x.submissions||[]).slice(-3).map((y:any)=>`<small>${money(y.price)} · ${evidence(y)}</small>`).join('<br>'):x.kind==='shop-reported'?T('Giá do tiệm đăng','Shop-posted'):evidence(x)+(x.photo?`<br><button class="btn small" data-photo="${esc(x.id)}">🖼 ${T('Xem ảnh (ghi nhật ký)','View photo (audited)')}</button>`:'')},
   {label:T('Báo cáo','Reports'),render:(x:any)=>(x.reports||[]).length?x.reports.map((r:any)=>`<small>${esc(r.reason)}${r.note?': '+esc(r.note):''} · ${ago(r.at)}</small>`).join('<br>'):'—'},
   {label:T('Người gửi','Contributor'),render:(x:any)=>x.kind==='reported'?(x.submissions||[]).slice(-3).map((y:any)=>`<small>${who(y.contributor)}</small>`).join('<br>'):x.kind==='shop-reported'?`<code>${esc(x.shop)}</code>`:who(x.contributor)},
   {label:T('Thao tác','Actions'),render:(x:any)=>`<div class="actions">${actions(x)}</div>`}],queueRows,{caption:T('Hàng đợi kiểm duyệt','Moderation queue')})
  :s.tab==='shops'?`<h2>${T('Đơn đăng ký tiệm','Shop applications')}</h2>${table([{label:T('Tiệm','Shop'),render:(a:any)=>`<strong>${esc(a.shopName)}</strong><br><small><code>${esc(a.username)}</code></small>`},{label:'ABN',render:(a:any)=>esc(a.abn||'—')},{label:T('Khu','Suburb'),render:(a:any)=>`${esc(a.suburb)} ${esc(a.postcode)} · ${esc(a.state)}`},{label:T('Gửi lúc','Applied'),render:(a:any)=>date(a.appliedAt)},{label:T('Trạng thái','Status'),render:(a:any)=>chip(a.status==='approved'?'green':a.status==='pending'?'amber':'red',({approved:T('Đã duyệt','Approved'),pending:T('Chờ duyệt','Pending'),rejected:T('Từ chối','Rejected'),revoked:T('Đã thu hồi','Revoked')} as any)[a.status]||a.status)},{label:'',render:(a:any)=>owner?`<div class="actions">${a.status!=='approved'?`<button class="btn small" data-shopact="shop-approve" data-u="${esc(a.username)}">${T('Duyệt','Approve')}</button>`:`<button class="btn small" data-shopact="shop-revoke" data-u="${esc(a.username)}">${T('Thu hồi','Revoke')}</button>`}${a.status==='pending'?`<button class="btn small" data-shopact="shop-reject" data-u="${esc(a.username)}">${T('Từ chối','Reject')}</button>`:''}</div>`:''}],d.applications,{caption:T('Đơn đăng ký tiệm','Shop applications')})}
   <h2>${T('Giá do tiệm đăng','Shop-posted prices')}</h2><p class="muted">${T('Tách riêng khỏi đồng thuận cộng đồng, hết hạn sau 14 ngày.','Kept separate from community consensus; expire after 14 days.')}</p>${table([{label:T('Tiệm','Shop'),render:(p:any)=>esc(p.shop?.name||'')},{label:T('Món','Item'),render:(p:any)=>esc(p.label)},{label:T('Giá','Price'),render:(p:any)=>money(p.price)},{label:T('Hết hạn','Expires'),render:(p:any)=>date(p.expiresAt)},{label:T('Báo cáo','Reports'),render:(p:any)=>num(p.openReports)},{label:T('Trạng thái','Status'),render:(p:any)=>p.hidden?chip('disabled',T('Đã ẩn','Hidden')):Date.parse(p.expiresAt)<Date.now()?chip('expired'):chip('active')}],d.shopPrices,{caption:T('Giá do tiệm đăng','Shop-posted prices')})}`
  :s.tab==='coi'?`<p class="muted">${T('Chỉ là tín hiệu để xem xét — hệ thống không tự chặn. Báo cáo bị gắn cờ không được tính vào xác nhận cho đến khi được duyệt.','Signals for review only — nothing is banned automatically. Flagged reports do not count toward confirmation until approved.')}</p>${table([{label:T('Tài khoản','Account'),render:(c:any)=>`<code>${esc(c.account)}</code>`},{label:T('Tin cậy','Trust'),render:(c:any)=>Number(c.trust).toFixed(2)},{label:T('Lượt gửi','Submissions'),render:(c:any)=>num(c.submissions)},{label:T('Tín hiệu','Signals'),render:(c:any)=>c.flags.map((f:string)=>chip('amber',flagName(f))).join(' ')},{label:'',render:(c:any)=>owner?`<button class="btn small" data-ca="${c.banned?'unban':'ban'}" data-account="${esc(c.account)}">${c.banned?T('Bỏ chặn','Unban'):T('Chặn người gửi','Ban contributor')}</button>`:''}],d.coi,{caption:T('Tín hiệu','Signals')})}`
  :`<div class="card"><ul class="plain">${[
   T('Chỉ nhận ảnh kệ giá (OCR khớp giá trong $0,01) hoặc dòng hóa đơn đã xác nhận; chụp trong 7 ngày, không ở tương lai; ảnh/dòng trùng bị từ chối.','Only shelf-tag photos (OCR within $0.01 of the price) or confirmed receipt lines; captured within 7 days, not in the future; duplicate photos/lines rejected.'),
   T('Đủ điều kiện: tài khoản ≥7 ngày; email khôi phục đã xác minh HOẶC thuộc gia đình ≥7 ngày; không bị khóa; ≤30 lượt/ngày/tài khoản, ≤60/ngày/mạng.','Eligible: account ≥7 days; verified recovery email OR member of a family ≥7 days; not disabled; ≤30/day per account, ≤60/day per network.'),
   T('Xác nhận: ≥2 gia đình khác nhau khớp giá (±2% hoặc ±$0,05) trong 7 ngày, mỗi gia đình một phiếu; hoặc 1 hóa đơn từ người tin cậy ≥0.7.','Confirmed: ≥2 different families match (±2% or ±$0.05) within 7 days, one vote per family; or 1 receipt from trust ≥0.7.'),
   T('Giữ để duyệt: ngoài 40%–250% trung vị 35 ngày (giá cộng đồng đã xác nhận + giá của gia đình người gửi).','Held: outside 40%–250% of the 35-day median (confirmed community + the submitter family’s prices).'),
   T('Tin cậy bắt đầu 0.5; +0.05 khi được gia đình khác xác nhận; −0.15 khi ≥2 gia đình báo khác hoặc bị từ chối; <0.3 thì không tính.','Trust starts at 0.5; +0.05 when corroborated; −0.15 when contradicted by ≥2 families or rejected; <0.3 never counts.'),
   T('Hết hạn: khuyến mãi tới ngày kết thúc; giá thường tính 14 ngày, hiện mờ tới 21 ngày rồi ẩn. Ảnh kiểm duyệt xóa sau khi duyệt hoặc 14 ngày.','Expiry: deals until their end date; regular prices count 14 days, greyed until 21, then hidden. Review photos are deleted after moderation or 14 days.')].map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>`}</div>`);
  const f=$('#cpf',el);f.onsubmit=async(e:any)=>{e.preventDefault();const on=f.on.checked;const v=await ask({title:on?T('Bật giá cộng đồng?','Turn community prices on?'):T('Tắt giá cộng đồng?','Turn community prices off?'),text:on?T('Người dùng đã đăng nhập ở NSW/QLD sẽ thấy và có thể chia sẻ giá cộng đồng.','Signed-in users in NSW/QLD will see and can share community prices.'):T('Giá cộng đồng sẽ ẩn với mọi người; dữ liệu được giữ lại.','Community prices will be hidden from everyone; data is kept.'),confirm:on?T('Bật','Turn on'):T('Tắt','Turn off')});if(!v)return;try{await post('settings-save',{patch:{flags:{communityPrices:on}}});toast(T('Đã lưu.','Saved.'));route()}catch(x){failMsg(x)}};
